result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/formgen/src/form.js", "content": "/**
 * Schema-driven accessible form generator.
 *
 * renderForm(schema) -> HTML string for a complete <form novalidate>.
 *
 * Schema entry: { name, label, type, required?, help?, options? }
 *   type: 'text' | 'email' | 'number' | 'select' | 'checkbox' | 'textarea'
 *   options: [{ value, label }]  (select only)
 */

/** Escape text nodes. */
export function escapeHtml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;');
}

/** Escape attribute values (quotes included). */
export function escapeAttr(value) {
  return escapeHtml(value).replaceAll('"', '&quot;').replaceAll("'", '&#39;');
}

/** Deterministic DOM id derived from the field name. */
export function fieldId(name) {
  return 'field-' + String(name).replace(/[^a-zA-Z0-9_-]+/g, '-').replace(/^-+|-+$/g, '');
}

const CONTROL_TYPES = new Set(['text', 'email', 'number', 'select', 'checkbox', 'textarea']);

function attrs(field) {
  const parts = [`id="${escapeAttr(fieldId(field.name))}"`, `name="${escapeAttr(field.name)}"`];
  if (field.required) parts.push('required');
  return parts.join(' ');
}

function requiredStar() {
  return ' <span aria-hidden="true">*</span>';
}

function renderSelect(field) {
  const options = (field.options || [])
    .map(
      (opt) =>
        `      <option value="${escapeAttr(opt.value)}">${escapeHtml(opt.label)}</option>`
    )
    .join('\n');
  return [
    `    <label for="${escapeAttr(fieldId(field.name))}">${escapeHtml(field.label)}${field.required ? requiredStar() : ''}</label>`,
    `    <select ${attrs(field)}>`,
    options,
    '    </select>',
  ].join('\n');
}

function renderCheckbox(field) {
  // Input comes first inside the label, then the visible text.
  return (
    `    <label for="${escapeAttr(fieldId(field.name))}">\n` +
    `      <input type="checkbox" ${attrs(field)}>\n` +
    `      ${escapeHtml(field.label)}${field.required ? requiredStar() : ''}\n` +
    `    </label>`
  );
}

function renderField(field) {
  if (!CONTROL_TYPES.has(field.type)) {
    throw new Error(`Unsupported field type: ${field.type}`);
  }
  const lines = [];
  const helpId = field.help ? `${fieldId(field.name)}-help` : null;

  if (field.type === 'checkbox') {
    lines.push(renderCheckbox(field));
  } else {
    lines.push(
      `    <label for="${escapeAttr(fieldId(field.name))}">${escapeHtml(field.label)}${field.required ? requiredStar() : ''}</label>`
    );
    switch (field.type) {
      case 'select':
        lines.push(renderSelect(field).split('\n').slice(1).join('\n'));
        break;
      case 'textarea':
        lines.push(`    <textarea ${attrs(field)}></textarea>`);
        break;
      default:
        lines.push(`    <input type="${field.type}" ${attrs(field)}>`);
    }
  }

  if (helpId) {
    lines.push(`    <p id="${escapeAttr(helpId)}" class="help">${escapeHtml(field.help)}</p>`);
  }
  return lines.join('\n');
}

/**
 * Render a schema into an accessible <form novalidate> HTML string.
 * @param {Array<{name:string,label:string,type:string,required?:boolean,help?:string,options?:Array<{value:string,label:string}>}>} schema
 * @returns {string}
 */
export function renderForm(schema) {
  if (!Array.isArray(schema)) throw new TypeError('renderForm expects an array of field schemas');
  const body = schema.map(renderField).join('\n');
  return `<form novalidate>\n${body}\n</form>`;
}
"})
