result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/formgen/test/form.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as cheerio from 'cheerio';
import { renderForm, fieldId } from '../src/form.js';

const $ = (html) => cheerio.load(html);

const ALL_TYPES = [
  { name: 'username', label: 'Username', type: 'text', required: true },
  { name: 'email_addr', label: 'Email', type: 'email' },
  { name: 'age', label: 'Age', type: 'number', required: true, help: 'Years on earth' },
  {
    name: 'color',
    label: 'Favorite color',
    type: 'select',
    options: [
      { value: 'red', label: 'Red' },
      { value: 'blue', label: 'Blue' },
    ],
  },
  { name: 'subscribe', label: 'Subscribe to newsletter', type: 'checkbox' },
  { name: 'bio', label: 'Bio', type: 'textarea', help: 'Tell us about yourself' },
];

describe('renderForm', () => {
  it('wraps everything in a form with novalidate', () => {
    const d = $(renderForm(ALL_TYPES));
    expect(d('form').length).toBe(1);
    expect(d('form').attr('novalidate')).toBeDefined();
  });

  it('pairs every label with its control via for/id deterministically', () => {
    const html = renderForm(ALL_TYPES);
    // Deterministic ids: rendering twice yields identical output.
    expect(renderForm(ALL_TYPES)).toBe(html);

    const d = $(html);
    for (const field of ALL_TYPES) {
      const id = fieldId(field.name);
      const control = d(`#${id}`);
      expect(control.length, `control #${id} exists`).toBe(1);
      const label = d(`label[for="${id}"]`);
      expect(label.length, `label[for=${id}] exists`).toBe(1);
    }
  });

  it('uses the correct element/tag per type', () => {
    const d = $(renderForm(ALL_TYPES));
    expect(d('#field-username').attr('type')).toBe('text');
    expect(d('#field-email_addr').attr('type')).toBe('email');
    expect(d('#field-age').attr('type')).toBe('number');
    expect(d('#field-color').is('select')).toBe(true);
    expect(d('#field-subscribe').attr('type')).toBe('checkbox');
    expect(d('#field-bio').is('textarea')).toBe(true);
  });

  it('adds aria-describedby only when help text exists, and the target matches', () => {
    const d = $(renderForm(ALL_TYPES));
    for (const field of ALL_TYPES) {
      const id = fieldId(field.name);
      const control = d(`#${id}`);
      if (field.help) {
        const helpId = `${id}-help`;
        expect(control.attr('aria-describedby')).toBe(helpId);
        const p = d(`p#${helpId}`);
        expect(p.length).toBe(1);
        expect(p.text()).toContain(field.help);
      } else {
        expect(control.attr('aria-describedby')).toBeUndefined();
      }
    }
  });

  it('required fields get the required attribute and a visible asterisk in the label', () => {
    const d = $(renderForm([
      { name: 'req_field', label: 'Required field', type: 'text', required: true },
      { name: 'opt_field', label: 'Optional field', type: 'text' },
    ]));
    expect(d('#field-req_field').attr('required')).toBeDefined();
    const reqLabel = d('label[for="field-req_field"]');
    const star = reqLabel.find('span[aria-hidden="true"]');
    expect(star.length).toBe(1);
    expect(star.text()).toBe('*');
    // Visible (not display:none / hidden attribute).
    expect(star.attr('hidden')).toBeUndefined();

    expect(d('#field-opt_field').attr('required')).toBeUndefined();
    expect(d('label[for="field-opt_field"] span[aria-hidden="true"]').length).toBe(0);
  });

  it('escapes hostile option labels and preserves option values', () => {
    const hostile = '<script>alert("xss")</script>';
    const d = $(renderForm([{
      name: 'evil',
      label: 'Evil select',
      type: 'select',
      options: [
        { value: 'a&b<c>"d"', label: hostile + ' & more' },
        { value: 'ok', label: 'Safe <b>choice</b>' },
      ],
    }]));
    const options = d('#field-evil option');
    expect(options.length).toBe(2);
    expect(options.eq(0).attr('value')).toBe('a&b<c>"d"');
    // Text is fully escaped: no script element injected.
    expect(options.eq(0).find('script').length).toBe(0);
    expect(options.eq(0).text()).toBe(hostile + ' & more');
    expect(options.eq(1).text()).toBe('Safe <b>choice</b>');
    // The raw HTML contains escaped entities rather than live markup.
    expect(renderForm([{ name: 'evil', label: 'x', type: 'select', options: [{ value: 'v', label: hostile }] }]))
      .not.toContain('<script>');
  });

  it('renders checkbox with input before its text inside the label', () => {
    const d = $(renderForm([{ name: 'terms', label: 'I accept terms', type: 'checkbox' }]));
    const label = d('label[for="field-terms"]');
    expect(label.length).toBe(1);
    const children = label.children().toArray();
    // First child element must be the input; text node follows it.
    expect(children[0].tagName).toBe('input');
    expect($(children[0]).attr('type')).toBe('checkbox');
    expect(label.text()).toContain('I accept terms');

    const html = renderForm([{ name: 'terms', label: 'T', type: 'checkbox' }]);
    const inputIdx = html.indexOf('<input');
    const textIdx = html.indexOf('T\n') > -1 ? html.lastIndexOf('T') : -1;
    expect(inputIdx).toBeGreaterThan(-1);
    expect(inputIdx).toBeLessThan(textIdx);
  });

  it('throws on unsupported types', () => {
    expect(() => renderForm([{ name: 'bad', label: 'Bad', type: 'password' }])).toThrow();
  });
});
"})
